/* @lc app=leetcode id=4033 lang=kotlin */ class Solution { fun up(b: LongArray, i: Int, d: Long): Unit = generateSequence(i + 1) { it + (it and -it) }.takeWhile { it < b.size }.forEach { b[it] += d } fun qs(b: LongArray, i: Int): Long = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { b[it] } fun validSubarrays(nums: IntArray, k: Int, queries: Array<IntArray>): BooleanArray = java.util.Random(20240607L).let { rnd -> LongArray(100_001) { rnd.nextLong() }.let { R -> nums.runningFold(0L) { a, x -> a xor R[x] }.let { px -> queries.indices.groupBy { queries[it][1] }.let { byR -> BooleanArray(queries.size).also { ans -> LongArray(nums.size + 2).let { bit -> IntArray(100_001) { -1 }.let { last -> nums.indices.forEach { r -> last[nums[r]].let { p -> (if (p >= 0) up(bit, p, -1L) else Unit).let { up(bit, r, 1L).let { last.set(nums[r], r).let { byR[r].orEmpty().forEach { qi -> ans.set(qi, qs(bit, r + 1) - qs(bit, queries[qi][0]) == k.toLong() && px[r + 1] == px[queries[qi][0]]) } } } } } } } } } } } } } }